33	export class FileDiscoveryService {
34	  private gitIgnoreFilter: GitIgnoreFilter | null = null;
35	  private geminiIgnoreFilter: IgnoreFileFilter | null = null;
36	  private customIgnoreFilter: IgnoreFileFilter | null = null;
37	  private combinedIgnoreFilter: GitIgnoreFilter | IgnoreFileFilter | null =
38	    null;
39	  private defaultFilterFileOptions: FilterFilesOptions = {
40	    respectGitIgnore: true,
41	    respectGeminiIgnore: true,
42	    customIgnoreFilePaths: [],
43	  };
44	  private projectRoot: string;
45	
46	  constructor(projectRoot: string, options?: FilterFilesOptions) {
47	    this.projectRoot = path.resolve(projectRoot);
48	    this.applyFilterFilesOptions(options);
49	    if (isGitRepository(this.projectRoot)) {
50	      this.gitIgnoreFilter = new GitIgnoreParser(this.projectRoot);
51	    }
52	    this.geminiIgnoreFilter = new IgnoreFileParser(
53	      this.projectRoot,
54	      GEMINI_IGNORE_FILE_NAME,
55	    );
56	    if (this.defaultFilterFileOptions.customIgnoreFilePaths?.length) {
57	      this.customIgnoreFilter = new IgnoreFileParser(
58	        this.projectRoot,
59	        this.defaultFilterFileOptions.customIgnoreFilePaths,
60	      );
61	    }
62	
63	    if (this.gitIgnoreFilter) {
64	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
65	      const customPatterns = this.customIgnoreFilter
66	        ? this.customIgnoreFilter.getPatterns()
67	        : [];
68	      // Create combined parser: .gitignore + .geminiignore + custom ignore
69	      this.combinedIgnoreFilter = new GitIgnoreParser(
70	        this.projectRoot,
71	        // customPatterns should go the last to ensure overwriting of geminiPatterns
72	        [...geminiPatterns, ...customPatterns],
73	      );
74	    } else {
75	      // Create combined parser when not git repo
76	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
77	      const customPatterns = this.customIgnoreFilter
78	        ? this.customIgnoreFilter.getPatterns()
79	        : [];
80	      this.combinedIgnoreFilter = new IgnoreFileParser(
81	        this.projectRoot,
82	        [...geminiPatterns, ...customPatterns],
83	        true,
84	      );
85	    }
86	  }
