88	  /**
89	   * Returns all absolute paths (files and directories) within the project root that should be ignored.
90	   */
91	  async getIgnoredPaths(options: FilterFilesOptions = {}): Promise<string[]> {
92	    const ignoredPaths: string[] = [];
93	
94	    /**
95	     * Recursively walks the directory tree to find ignored paths.
96	     */
97	    const walk = async (currentDir: string) => {
98	      let dirEntries: fs.Dirent[];
99	      try {
100	        dirEntries = await fs.promises.readdir(currentDir, {
101	          withFileTypes: true,
102	        });
103	      } catch (error: unknown) {
104	        if (
105	          isNodeError(error) &&
106	          (error.code === 'EACCES' || error.code === 'ENOENT')
107	        ) {
108	          // Stop if the directory is inaccessible or doesn't exist
109	          debugLogger.debug(
110	            `Skipping directory ${currentDir} due to ${error.code}`,
111	          );
112	          return;
113	        }
114	        throw error;
115	      }
116	
117	      // Traverse sibling directories concurrently to improve performance.
118	      await Promise.all(
119	        dirEntries.map(async (entry) => {
120	          const fullPath = path.join(currentDir, entry.name);
121	
122	          if (entry.isDirectory()) {
123	            // Optimization: If a directory is ignored, its contents are not traversed.
124	            if (this.shouldIgnoreDirectory(fullPath, options)) {
125	              ignoredPaths.push(fullPath);
126	            } else {
127	              await walk(fullPath);
128	            }
129	          } else {
130	            if (this.shouldIgnoreFile(fullPath, options)) {
131	              ignoredPaths.push(fullPath);
132	            }
133	          }
134	        }),
135	      );
136	    };
137	
138	    await walk(this.projectRoot);
139	    return ignoredPaths;
140	  }
