142	  private applyFilterFilesOptions(options?: FilterFilesOptions): void {
143	    if (!options) return;
144	
145	    if (options.respectGitIgnore !== undefined) {
146	      this.defaultFilterFileOptions.respectGitIgnore = options.respectGitIgnore;
147	    }
148	    if (options.respectGeminiIgnore !== undefined) {
149	      this.defaultFilterFileOptions.respectGeminiIgnore =
150	        options.respectGeminiIgnore;
151	    }
152	    if (options.customIgnoreFilePaths) {
153	      this.defaultFilterFileOptions.customIgnoreFilePaths =
154	        options.customIgnoreFilePaths;
155	    }
156	  }
