159	   * Filters a list of file paths based on ignore rules.
160	   *
161	   * NOTE: Directory paths must include a trailing slash to be correctly identified and
162	   * matched against directory-specific ignore patterns (e.g., 'dist/').
163	   */
164	  filterFiles(filePaths: string[], options: FilterFilesOptions = {}): string[] {
165	    return filePaths.filter((filePath) => {
