21	 * An ignore file parser that reads the ignore files from the project root.
22	 */
23	export class IgnoreFileParser implements IgnoreFileFilter {
24	  private projectRoot: string;
25	  private patterns: string[] = [];
26	  private ig = ignore();
27	  private readonly fileNames: string[];
28	
29	  constructor(
30	    projectRoot: string,
31	    // The order matters: files listed earlier have higher priority.
32	    // It can be a single file name/pattern or an array of file names/patterns.
33	    input: string | string[],
34	    isPatterns = false,
35	  ) {
36	    this.projectRoot = path.resolve(projectRoot);
37	    if (isPatterns) {
38	      this.fileNames = [];
39	      const patterns = Array.isArray(input) ? input : [input];
40	      this.patterns.push(...patterns);
41	      this.ig.add(patterns);
42	    } else {
43	      this.fileNames = Array.isArray(input) ? input : [input];
44	      this.loadPatternsFromFiles();
45	    }
46	  }
47	
48	  private loadPatternsFromFiles(): void {
49	    // Iterate in reverse order so that the first file in the list is processed last.
50	    // This gives the first file the highest priority, as patterns added later override earlier ones.
51	    for (const fileName of [...this.fileNames].reverse()) {
52	      const patterns = this.parseIgnoreFile(fileName);
53	      this.patterns.push(...patterns);
54	      this.ig.add(patterns);
55	    }
56	  }
57	
58	  private parseIgnoreFile(fileName: string): string[] {
59	    const patternsFilePath = path.join(this.projectRoot, fileName);
60	    let content: string;
61	    try {
62	      content = fs.readFileSync(patternsFilePath, 'utf-8');
63	    } catch {
64	      debugLogger.debug(
65	        `Ignore file not found: ${patternsFilePath}, continue without it.`,
66	      );
67	      return [];
68	    }
69	
70	    debugLogger.debug(`Loading ignore patterns from: ${patternsFilePath}`);
71	
72	    return (content ?? '')
73	      .split(/\r\n|\n|\r/)
74	      .map((p) => p.trim())
75	      .filter((p) => p !== '' && !p.startsWith('#'));
76	  }
77	
78	  isIgnored(filePath: string, isDirectory: boolean): boolean {
79	    if (this.patterns.length === 0) {
80	      return false;
81	    }
82	
83	    const normalizedPath = getNormalizedRelativePath(
84	      this.projectRoot,
85	      filePath,
86	      isDirectory,
87	    );
88	    if (
89	      normalizedPath === null ||
90	      normalizedPath === '' ||
91	      normalizedPath === '/'
92	    ) {
93	      return false;
94	    }
95	
96	    return this.ig.ignores(normalizedPath);
97	  }
98	
99	  getPatterns(): string[] {
100	    return this.patterns;
101	  }
102	
103	  getIgnoreFilePaths(): string[] {
104	    return this.fileNames
105	      .slice()
106	      .reverse()
107	      .map((fileName) => path.join(this.projectRoot, fileName))
108	      .filter((filePath) => fs.existsSync(filePath));
109	  }
110	
111	  /**
112	   * Returns true if at least one ignore file exists and has patterns.
113	   */
114	  hasPatterns(): boolean {
115	    return this.patterns.length > 0;
116	  }
117	}
